#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps the NewObject-created tracker reachable by GC.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UArenaScoreTracker* created with NewObject(this) but not marked UPROPERTY, so the garbage collector does not treat it as a root. The GC pass at 2026.10.28-21.05.13 purged it; the goal at 21:05:27 then called ScoreTracker->AddPoints on the freed object, causing the access violation at ArenaScoreTracker.cpp:18 (reading 0xffffffffffffffff). Fixed in ArenaGameMode.h by declaring it UPROPERTY() TObjectPtr<UArenaScoreTracker>.",
  "no_colors_cause": "The palette /Game/Data/Palettes/DA_Primary is reached only through the hardcoded LoadObject path in AArenaGameMode::BeginPlay, so the cooker sees no reference to the package. With bCookAll=False and MapsToCook limited to /Game/Maps/Arena, the palette was never cooked into the pak. In the packaged build LoadObject fails (log: Couldn't find file for package /Game/Data/Palettes/DA_Primary) and the HUD uses the fallback gray. Fixed in DefaultGame.ini by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\")."
}
